contract InvMutTest {
    C c;

    constructor(C _c) {
        c = _c;
    }

    function run(address to, uint amount) public {
        require(msg.sender == address(this));

        address[] memory tos = new address[](1);
        tos[0] = to;
        uint[] memory vs = new uint[](1);
        vs[0] = amount;

        bool representable = (amount == 0) || ((amount * 1000000000000000000) / amount == 1000000000000000000);

        bool reverted;
        bool ok;
        try c.transfer(tos, vs) returns (bool _ok) {
            ok = _ok;
            reverted = false;
        } catch {
            ok = false;
            reverted = true;
        }

        assert(ok == representable && reverted == !representable);
    }

    receive() external payable {}
